const $=id=>document.getElementById(id);const modes={blade:{name:'Клинок',hint:'Ровно 2 клетки до врага; нет смежных врагов. Сначала перемещение на 1 клетку.',effect:'Быстрая Стычка → Усилить себя'},pole:{name:'Древко',hint:'Нужны ровно 2 смежных врага.',effect:'Быстрая Стычка → толкнуть на 3 клетки → Подбросить'},chain:{name:'Цепь',hint:'Нужна одна цель ровно в 4 клетках.',effect:'Быстрая Стычка → Разорвать цель'}};
let ap=3,mode=null,selected=[],destination=null,used=[],fixture='chain';const hero={x:2,y:2};const enemies=()=>fixture==='pole'?[{id:'a',name:'Враг А',x:2,y:1},{id:'b',name:'Враг Б',x:3,y:2}]:[{id:'a',name:'Враг А',x:fixture==='blade'?4:6,y:2},{id:'b',name:'Враг Б',x:0,y:0}];
function reason(){if(!mode)return 'Выберите действие.';if(used.includes(mode))return 'Это Вооружение уже экипировали в этом демо-Ходу.';if(ap<1)return 'Недостаточно ОД: нужно 1.';if(fixture!==mode)return modes[mode].hint;if(mode==='blade'&&!destination)return 'Выберите отмеченную клетку перемещения; затем цель.';if(selected.length!==(mode==='pole'?2:1))return mode==='pole'?'Выберите обоих смежных врагов.':'Выберите врага А.';return '';}
function target(id){if(!mode)return;if(fixture!==mode)return;if(mode==='blade'&&!destination)return;if(id==='b'&&mode!=='pole')return;selected=selected.includes(id)?selected.filter(x=>x!==id):[...selected,id];render();}
function render(){ $('ap').textContent=ap+' ОД';$('actions').innerHTML=Object.entries(modes).map(([key,m])=>`<button data-mode="${key}" aria-pressed="${mode===key}"><b>${m.name} · Стычка · 1 ОД</b><small>${used.includes(key)?'Недоступно: уже экипировали в этот Ход':m.hint}</small></button>`).join('');$('actions').querySelectorAll('button').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;selected=[];destination=null;render()});$('map').innerHTML='';for(let y=0;y<5;y++)for(let x=0;x<7;x++){const e=enemies().find(e=>e.x===x&&e.y===y),h=hero.x===x&&hero.y===y,m=mode==='blade'&&fixture==='blade'&&x===3&&y===2;const b=document.createElement('button');b.textContent=e?'В':h?'Р':m?'○':'·';b.className=(e?'enemy':h?'hero':m?'move':'')+(e&&selected.includes(e.id)||m&&destination?' chosen':'');b.setAttribute('aria-label',e?`${e.name}, клетка ${x}, ${y}`:h?'Рааша':m?'Переместиться на одну клетку вправо':`Пустая клетка ${x}, ${y}`);b.onclick=()=>{if(e)target(e.id);if(m){destination={x,y};selected=[];render()}};$('map').append(b)}$('step').textContent=mode==='blade'&&!destination?'2. Выберите клетку, затем цель':'2. Выберите цель';$('targets').innerHTML=mode?enemies().map(e=>{const why=fixture!==mode?modes[mode].hint:mode==='blade'&&!destination?'Сначала выберите клетку перемещения':e.id==='b'&&mode!=='pole'?'Не соответствует расстоянию Вооружения':'';return `<button data-target="${e.id}" aria-pressed="${selected.includes(e.id)}" ${why?'disabled':''}>${e.name}${selected.includes(e.id)?' · выбрана':''}<small>${why||'Допустимая цель'}</small></button>`}).join(''):'<p>Цели появятся после выбора действия.</p>';$('targets').querySelectorAll('button').forEach(b=>b.onclick=()=>target(b.dataset.target));$('preview').textContent=mode?`${modes[mode].name} · 1 ОД · ${selected.map(id=>enemies().find(e=>e.id===id).name).join(', ')||'цель не выбрана'}`:'Выберите действие';$('status').textContent=reason()||modes[mode].effect+'. Готово к подтверждению. Ничего не потрачено.';$('confirm').disabled=!!reason();$('maphint').textContent=mode?reason()||'Проверьте итог внизу и подтвердите.':'Выберите действие справа, затем цель на карте.';}
$('fixture').onchange=e=>{fixture=e.target.value;mode=null;selected=[];destination=null;render()};$('cancel').onclick=()=>{mode=null;selected=[];destination=null;render();$('status').textContent='Выбор отменён. ОД не потрачены.'};$('confirm').onclick=()=>{if(reason())return;const entry=document.createElement('li');entry.textContent=`ДЕМО: ${modes[mode].name}, ${selected.join(', ')}, −1 ОД. Бросок, реакции и эффекты не выполнялись.`;$('log').append(entry);ap--;used.push(mode);mode=null;selected=[];destination=null;render();$('status').textContent='Демо подтверждено: списан 1 ОД. Разрешение атаки не подключено.'};$('reset').onclick=()=>{ap=3;mode=null;selected=[];destination=null;used=[];$('log').innerHTML='';render()};document.addEventListener('keydown',e=>{if(e.key==='Escape')$('cancel').click()});render();
